'use strict';
const fs = require('fs');
const m = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const cells = m.detail.diagrams[0].cells;
const ids = cells.map(c => c.id);
const cellThreats = cells.flatMap(c => (c.data && c.data.threats) || []);
const root = m.threats;

const results = [];
const check = (name, ok, extra='') => results.push(`${ok ? 'PASS' : 'FAIL'}  ${name}${extra ? ' :: ' + extra : ''}`);

check('threats >= 15', root.length >= 15, `count=${root.length}`);
const cats = [...new Set(root.map(t => t.stride_category))];
check('6 STRIDE categories', cats.length === 6, cats.join(','));
const grouped = {};
root.forEach(t => grouped[t.stride_category] = (grouped[t.stride_category]||0)+1);
check('min 2 per category', cats.length === 6 && Object.values(grouped).every(v => v>=2), JSON.stringify(grouped));
check('targets exist', root.every(t => ids.includes(t.target)));
const a = cellThreats.map(t=>t.id).sort();
const b = root.map(t=>t.id).sort();
check('cell threats == root threats', JSON.stringify(a)===JSON.stringify(b), `${a.length} vs ${b.length}`);
check('9 boundaries', cells.filter(c=>c.shape==='trust-boundary-box').length>=9);
check('20 elements', cells.filter(c=>['process','actor','store'].includes(c.shape)).length>=20);
check('31 flows', cells.filter(c=>c.shape==='flow').length>=31);
check('TMR ids present', ['P-CH1','P-CH2','P-CH3','P-ARB','P-ARB2','F-14','F-15','F-16'].every(x=>ids.includes(x)));
check('flow protocol transport/port', cells.filter(c=>c.shape==='flow').every(c=>/^(TCP|UDP)\/[0-9]+/.test(c.data.protocol||'')));
const cwes = [...new Set(root.flatMap(t=>t.cwe||[]))];
check('>=10 distinct CWE', cwes.length>=10, `count=${cwes.length}`);
check('unique threat ids', new Set(root.map(t=>t.id)).size===root.length);
check('severity values valid', root.every(t=>['Critical','High','Medium','Low'].includes(t.severity)));
check('likelihood 1-5', root.every(t=>Number.isInteger(t.likelihood)&&t.likelihood>=1&&t.likelihood<=5));
check('impact 1-5', root.every(t=>Number.isInteger(t.impact_score)&&t.impact_score>=1&&t.impact_score<=5));
check('invariants present', root.every(t=>Array.isArray(t.invariants)&&t.invariants.length>=1));
check('cwe present', root.every(t=>Array.isArray(t.cwe)&&t.cwe.length>=1));
// cell threat required fields per schema
const req = ['description','mitigation','severity','status','title','type'];
check('cell threat required fields', cellThreats.every(t=>req.every(f=>typeof t[f]==='string'||typeof t[f]==='number')));
check('cell threat severity Critical->High', cellThreats.every(t=>['High','Medium','Low'].includes(t.severity)));
check('cell threat type valid', cellThreats.every(t=>['Spoofing','Tampering','Repudiation','Information disclosure','Denial of service','Elevation of privilege'].includes(t.type)));
check('score = l*i', root.every(t=>{const ct=cellThreats.find(c=>c.id===t.id); return ct.score===String(t.likelihood*t.impact_score);}));
check('no dup target+category', (()=>{const s=new Set();for(const t of root){const k=t.target+'|'+t.stride_category;if(s.has(k))return false;s.add(k);}return true;})());
check('hasOpenThreats true iff threats', cells.every(c=>{
  const has=(c.data&&c.data.threats&&c.data.threats.length>0);
  return (c.data.hasOpenThreats===!!has);
}));
check('red stroke iff threats', cells.filter(c=>['process','actor','store','flow'].includes(c.shape)).every(c=>{
  const has=(c.data&&c.data.threats&&c.data.threats.length>0);
  const stroke = c.shape==='flow' ? c.attrs.line.stroke : (c.attrs.body?c.attrs.body.stroke:c.attrs.topLine.stroke);
  return has ? stroke==='red' : stroke==='#333333';
}));
// containment check
const bnd = cells.filter(c=>c.shape==='trust-boundary-box');
const inside = (el, b) => el.position.x>=b.position.x && el.position.y>=b.position.y &&
  el.position.x+el.size.width<=b.position.x+b.size.width &&
  el.position.y+el.size.height<=b.position.y+b.size.height;
let containmentOk = true; const bad=[];
for (const el of cells.filter(c=>['process','actor','store'].includes(c.shape))) {
  if (!bnd.some(b=>inside(el,b))) { containmentOk=false; bad.push(el.id); }
}
check('elements inside a boundary', containmentOk, bad.join(','));
check('diagramThreat count matches threatTop', m.detail.threatTop === Math.max(...cellThreats.map(t=>t.number)));

console.log(results.join('\n'));
console.log('\nFAILS:', results.filter(r=>r.startsWith('FAIL')).length);

